static MOD_UNUSED void monsters_copy_str(char* dst, int cap, const char* src) {
    int i = 0;
    if (!dst || cap <= 0) return;
    if (!src) { dst[0] = '\0'; return; }
    while (src[i] != '\0' && i < cap - 1) { dst[i] = src[i]; ++i; }
    dst[i] = '\0';
}

static MOD_UNUSED int monsters_is_int_key(const char* key) {
    if (!key) return 0;
    return strcmp(key, "state") == 0 || strcmp(key, "level") == 0 || strcmp(key, "dir") == 0 ||
           strcmp(key, "walk_state") == 0 || strcmp(key, "decor") == 0 || strcmp(key, "live") == 0 ||
           strcmp(key, "facing") == 0 || strcmp(key, "move_state") == 0 ||
           strcmp(key, "turns") == 0 || strcmp(key, "blend") == 0;
}

static MOD_UNUSED void monsters_pack_scalar(const char* key, float v, AmodValue* out) {
    memset(out, 0, sizeof(*out));
    if (monsters_is_int_key(key)) {
        out->kind = AMOD_VALUE_INT;
        out->integer = (int)v;
    } else {
        out->kind = AMOD_VALUE_FLOAT;
        out->count = 1;
        out->numbers[0] = v;
    }
}

static MOD_UNUSED float monsters_unpack_scalar(const AmodValue* v) {
    if (!v) return 0.0f;
    if (v->kind == AMOD_VALUE_INT || v->kind == AMOD_VALUE_BOOL) return (float)v->integer;
    if (v->kind == AMOD_VALUE_FLOAT && v->count >= 1) return v->numbers[0];
    return 0.0f;
}

static MOD_UNUSED int monsters_match_filter(const char* filter, const char* name, const char* tag) {
    if (!filter || filter[0] == '\0') return 1;
    if (name && strcmp(name, filter) == 0) return 1;
    if (tag && tag[0] != '\0' && strcmp(tag, filter) == 0) return 1;
    return 0;
}

