static MOD_UNUSED int monsters_place_any(int roomIndex, const char* name, int col, int row, int facing, int level, int decor, int pos3, int pos4, float attackDist, const char* tag) {
    AmodMonsterPlacement p;
    if (!API->monsters || !name || !name[0]) return 0;
    if (roomIndex < 0 && facing == 1 && level == 0 && decor == 0 && pos3 == 0 && pos4 == 0 && attackDist == 5.0f && (!tag || !tag[0])) {
        if (API->monsters->Place) return API->monsters->Place(SELF, name, col, row);
    }
    memset(&p, 0, sizeof(p));
    p.structSize = sizeof(p);
    p.name = name;
    p.column = col;
    p.row = row;
    p.facing = facing;
    p.level = level;
    p.decor = decor;
    p.extraA = pos3;
    p.extraB = pos4;
    p.attackDist = attackDist;
    p.tag = (tag && tag[0]) ? tag : 0;
    if (roomIndex < 0) return API->monsters->PlaceEx ? API->monsters->PlaceEx(SELF, &p) : 0;
    return API->monsters->PlaceIn ? API->monsters->PlaceIn(SELF, roomIndex, &p) : 0;
}

