static MOD_UNUSED void monsters_bind_defined_think(const char* name, AmodMonsterThinkHandler fn) {
    int i;
    MonstersDefThinkSlot* slot = 0;
    if (!name || !name[0] || !fn) return;
    for (i = 0; i < g_monsters_def_think_cnt; ++i) {
        if (strcmp(g_monsters_def_thinks[i].name, name) == 0) { slot = &g_monsters_def_thinks[i]; break; }
    }
    if (!slot && g_monsters_def_think_cnt < MonstersMaxSlots) {
        slot = &g_monsters_def_thinks[g_monsters_def_think_cnt++];
        memset(slot, 0, sizeof(*slot));
        monsters_copy_str(slot->name, 64, name);
    }
    if (!slot || slot->cnt >= MonstersMaxHooks) return;
    slot->fns[slot->cnt++] = fn;
    if (API->monsters && API->monsters->DefineBehaviour) {
        API->monsters->DefineBehaviour(SELF, slot->name, monsters_defined_think_mux, slot);
    }
}

