static int __cdecl monsters_kind_mux(const AmodMonsterKindInfo* info, void* user) {
    MonstersKindSlot* slot = (MonstersKindSlot*)user;
    int i, res;
    if (!slot || !info) return 0;
    g_monsters_cur_kind_id = info->kind;
    if (info->event == AMOD_MONSTER_EVENT_BUILD) {
        AmodMonsterBody* prev = g_monsters_cur_body;
        int ok = 1;
        g_monsters_cur_body = info->body;
        if (info->body) {
            monsters_copy_str(g_monsters_body_name, MonstersTextCap, info->body->name);
            monsters_copy_str(g_monsters_body_tag, MonstersTextCap, info->body->tag);
        } else {
            g_monsters_body_name[0] = '\0';
            g_monsters_body_tag[0] = '\0';
        }
        for (i = 0; i < slot->buildCnt; ++i) {
            if (slot->buildFns[i] && slot->buildFns[i](info, 0) == 0) { ok = 0; break; }
        }
        g_monsters_cur_body = prev;
        return ok;
    }
    if (info->event == AMOD_MONSTER_EVENT_UPDATE) {
        if (info->think) monsters_cache_think(info->think);
        for (i = 0; i < slot->updateCnt; ++i) {
            if (slot->updateFns[i]) slot->updateFns[i](info, 0);
        }
        return 0;
    }
    if (info->event == AMOD_MONSTER_EVENT_TOUCH) {
        int verdict = AMOD_MONSTER_ALSO_GAME;
        if (info->touch) monsters_cache_touch(info->touch);
        for (i = 0; i < slot->touchCnt; ++i) {
            g_monsters_touch_verdict = AMOD_MONSTER_TOUCH_DEFAULT;
            res = slot->touchFns[i] ? slot->touchFns[i](info, 0) : AMOD_MONSTER_ALSO_GAME;
            if (res != AMOD_MONSTER_ALSO_GAME) verdict = AMOD_MONSTER_INSTEAD_OF_GAME;
        }
        return verdict;
    }
    return 0;
}

static MOD_UNUSED int monsters_ensure_kind(const char* name) {
    int i;
    MonstersKindSlot* slot = 0;
    if (!name || !name[0]) return -1;
    for (i = 0; i < g_monsters_kind_cnt; ++i) {
        if (strcmp(g_monsters_kinds[i].name, name) == 0) { slot = &g_monsters_kinds[i]; break; }
    }
    if (!slot) {
        if (g_monsters_kind_cnt >= MonstersMaxSlots) return -1;
        slot = &g_monsters_kinds[g_monsters_kind_cnt++];
        memset(slot, 0, sizeof(*slot));
        monsters_copy_str(slot->name, 64, name);
    }
    if (slot->kindId == 0 && API->monsters && API->monsters->RegisterKind) {
        slot->kindId = API->monsters->RegisterKind(SELF, slot->name, monsters_kind_mux, slot);
    }
    return (int)(slot - g_monsters_kinds);
}

static MOD_UNUSED void monsters_bind_kind(const char* name, int phase, AmodMonsterKindHandler fn) {
    int idx = monsters_ensure_kind(name);
    MonstersKindSlot* slot;
    if (idx < 0 || !fn) return;
    slot = &g_monsters_kinds[idx];
    if (phase == 0 && slot->buildCnt < MonstersMaxHooks) slot->buildFns[slot->buildCnt++] = fn;
    else if (phase == 1 && slot->updateCnt < MonstersMaxHooks) slot->updateFns[slot->updateCnt++] = fn;
    else if (phase == 2 && slot->touchCnt < MonstersMaxHooks) slot->touchFns[slot->touchCnt++] = fn;
}

static MOD_UNUSED int monsters_kind_id_of(const char* name) {
    int i;
    if (!name || !name[0]) return 0;
    for (i = 0; i < g_monsters_kind_cnt; ++i) {
        if (strcmp(g_monsters_kinds[i].name, name) == 0) return g_monsters_kinds[i].kindId;
    }
    return 0;
}

static MOD_UNUSED int monsters_place_kind(const char* kindName, int roomIndex, int col, int row, int facing, int level, const char* tag) {
    int idx = monsters_ensure_kind(kindName);
    AmodMonsterPlacement p;
    if (idx < 0 || g_monsters_kinds[idx].kindId == 0 || !API->monsters || !API->monsters->PlaceKind) return 0;
    memset(&p, 0, sizeof(p));
    p.structSize = sizeof(p);
    p.column = col;
    p.row = row;
    p.facing = facing;
    p.level = level;
    p.tag = (tag && tag[0]) ? tag : 0;
    return API->monsters->PlaceKind(SELF, g_monsters_kinds[idx].kindId, roomIndex, &p);
}

