static MOD_UNUSED void monsters_cancel_token(AmodToken* tok, int which) {
    if (!tok || *tok == AMOD_INVALID_TOKEN || !API->monsters) return;
    if (which == 1 && API->monsters->RemoveKillHandler) API->monsters->RemoveKillHandler(SELF, *tok);
    else if (which == 2 && API->monsters->RemoveTouchHandler) API->monsters->RemoveTouchHandler(SELF, *tok);
    else if (which == 3 && API->monsters->RemoveSpawnHandler) API->monsters->RemoveSpawnHandler(SELF, *tok);
    else if (which == 4 && API->monsters->RemovePlaceHandler) API->monsters->RemovePlaceHandler(SELF, *tok);
    else if (API->monsters->Cancel) API->monsters->Cancel(SELF, *tok);
    *tok = AMOD_INVALID_TOKEN;
}
